// Turns your settings into the Google Trends Actor's input.
const s = $('Your settings').first().json;
const keywords = String(s.keywords || '').split(',').map(k => k.trim()).filter(Boolean);
if (!keywords.length) throw new Error('Add at least one keyword in "Your settings".');
if (keywords.length > 50) throw new Error('Use at most 50 keywords per run, so the Actor call finishes within 5 minutes.');
const components = ['relatedQueries'];
if (s.includeTopics) components.push('relatedTopics');
return [{ json: { actorInput: {
  keywords,
  preset: 'custom',
  components,             // only the parts this workflow needs, so you only pay for those
  geo: s.country,
  timeRange: s.timeRange,
  maxTopicsWaitMinutes: 3 // keeps each run short; related topics Google holds back longer are skipped (not charged)
} } }];

// Keeps the searches that are really rising in your niche:
// - every rising related query and related topic, scored by growth ("Breakout" counts highest)
// - drops noise. Google Trends data in 2026 carries junk from bots and AI agents: generic searches like
//   "how to make sushi" or "what is a 401k" as Breakouts under unrelated keywords, and prompt-like searches
//   ("explain what X is and its main benefits"). Three rules remove it:
//   1. off-topic: shares no real word with your keyword or niche (turn off with onlyRelated = false)
//   2. prompt-like: starts like an instruction to an AI, or is 9+ words long
//   3. repeated junk: the same search under several of your keywords while sharing no word with them
// - spreads the ideas across your keywords, and skips anything you already got in the last 8 weeks
const s = $('Your settings').first().json;
const STOP = new Set(['for', 'the', 'and', 'with', 'from', 'that', 'this', 'your', 'you', 'how', 'what', 'when',
  'why', 'who', 'which', 'can', 'does', 'best', 'top', 'near', 'are', 'was', 'use', 'using', 'new', 'free', 'good',
  'get', 'vs', 'not', 'all', 'about', 'into', 'like', 'more', 'most', 'make', 'way', 'ways']);
const words = t => String(t).toLowerCase().split(/[^\p{L}\p{N}]+/u).filter(w => w.length > 2 && !STOP.has(w));
const stems = t => new Set(words(t).map(w => w.slice(0, 5)));
const score = g => /breakout/i.test(g || '') ? 5000 : (parseInt(String(g || '').replace(/[^0-9]/g, ''), 10) || 0);
const PROMPT = /^(explain|describe|write|list|give me|tell me|summarize|compare|create|generate|provide)\b/i;
const nicheStems = stems(`${s.niche || ''}`);

const rows = [];
let skippedKeywords = 0;
for (const { json: it } of $input.all()) {
  if (!['complete', 'partial'].includes(it.status)) { skippedKeywords++; continue; } // e.g. low volume: nothing to read
  for (const q of it.relatedQueries?.rising || [])
    rows.push({ keyword: it.keyword, kind: 'query', text: q.query, topicType: '', growth: q.growth || '', score: score(q.growth) });
  for (const t of it.relatedTopics?.rising || [])
    rows.push({ keyword: it.keyword, kind: 'topic', text: t.title, topicType: t.type || '', growth: t.growth || '', score: score(t.growth) });
}

const under = {};
for (const r of rows) (under[r.text.toLowerCase()] ??= new Set()).add(r.keyword);
const minKeywords = Number(s.noiseMinKeywords) || 3;
const related = r => { const k = new Set([...stems(r.keyword), ...nicheStems]); return [...stems(r.text)].some(w => k.has(w)); };
const isNoise = r =>
  (s.onlyRelated !== false && !related(r))
  || (r.kind === 'query' && (PROMPT.test(r.text) || words(r.text).length >= 9))
  || (r.kind === 'query' && under[r.text.toLowerCase()].size >= minKeywords && !related(r));

const memory = $getWorkflowStaticData('global');
memory.seen ??= {};
const now = Date.now();
for (const [k, t] of Object.entries(memory.seen)) if (now - t > 8 * 7 * 86400e3) delete memory.seen[k];

const best = {};
let noise = 0, repeats = 0;
for (const r of rows) {
  if (isNoise(r)) { noise++; continue; }
  const key = `${r.kind}|${r.text.toLowerCase()}`;
  if (memory.seen[key]) { repeats++; continue; }
  if (!best[key] || r.score > best[key].score) best[key] = r;
}
// spread across keywords: at most a fair share per keyword, so one keyword can't take every slot
const limit = Number(s.ideasPerRun) || 10;
const keywordCount = new Set(rows.map(r => r.keyword)).size || 1;
const perKeyword = Math.max(2, Math.ceil(limit / keywordCount));
const used = {};
const picked = [];
for (const r of Object.values(best).sort((a, b) => b.score - a.score)) {
  if (picked.length >= limit) break;
  if ((used[r.keyword] = (used[r.keyword] || 0) + 1) <= perKeyword) picked.push(r);
}
const stats = { risingFound: rows.length, noiseRemoved: noise, alreadySent: repeats, keywordsWithoutData: skippedKeywords };
return picked.map(r => ({ json: { ...r, stats } }));

// One request for all risers: cheaper and more consistent than one call per idea.
const s = $('Your settings').first().json;
const risers = $input.all().map(i => i.json);
const list = risers.map((r, n) => `${n + 1}. ${r.kind === 'topic' ? 'Topic' : 'Search'} "${r.text}"`
  + `${r.topicType ? ` (${r.topicType})` : ''}, rising ${r.growth} under "${r.keyword}"`).join('\n');
const prompt = `I make content about: ${s.niche || s.keywords}.\n`
  + `These searches are rising on Google right now (${s.country}, ${s.timeRange}):\n${list}\n\n`
  + 'For each numbered item, write one content idea I could publish this week. '
  + 'Reply with JSON only, in this shape: {"ideas":[{"n":1,"title":"...","angle":"what to cover and why people search it now",'
  + '"hook":"the first line of the post","format":"blog post | short video | carousel | newsletter"}]}. '
  + 'Do not invent statistics. If an item has nothing to do with my niche, set its title to "skip".';
return [{ json: { body: {
  model: s.aiModel,
  temperature: 0.6,
  response_format: { type: 'json_object' },
  messages: [
    { role: 'system', content: 'You are a practical content strategist. You write specific ideas, never generic ones.' },
    { role: 'user', content: prompt },
  ],
} } }];

// Matches the AI's ideas back to the rising searches they came from; drops the ones it marked "skip".
const risers = $('Pick the real risers').all().map(i => i.json);
const content = $input.first().json.choices?.[0]?.message?.content;
let ideas;
try {
  ideas = JSON.parse(content).ideas || [];
} catch (e) {
  throw new Error('The AI reply was not the JSON asked for: ' + String(content).slice(0, 300));
}
const byNumber = Object.fromEntries(ideas.map(i => [Number(i.n), i]));
return risers
  .map((r, n) => ({ r, i: byNumber[n + 1] || {} }))
  .filter(({ i }) => i.title && i.title.toLowerCase() !== 'skip')
  .map(({ r, i }) => ({ json: { ...r, title: i.title, angle: i.angle || '', hook: i.hook || '', format: i.format || '' } }));

// Without AI: a plain idea per rising search, so the planner works with no AI key at all.
const cap = t => t.charAt(0).toUpperCase() + t.slice(1);
return $input.all().map(({ json: r }) => {
  const t = r.text;
  const question = /^(how|what|why|when|which|who|can|is|are|does|do|should)\b/i.test(t);
  const format = question ? 'blog post that answers the question'
    : /near me|open now/i.test(t) ? 'local page'
    : r.kind === 'topic' && /brand|company|product/i.test(r.topicType) ? 'review or comparison'
    : 'short video or carousel';
  return { json: { ...r,
    title: question ? `${cap(t)}?` : `${cap(t)}: why everyone is searching for it now`,
    angle: `Searches for "${t}" are up ${r.growth} around "${r.keyword}". Explain what changed and answer what people want to know.`,
    hook: question ? `${cap(t)}? Here is the short answer.` : `Searches for "${t}" just jumped ${r.growth}.`,
    format,
  } };
});

// One row per idea for your review queue, and remembers what was sent so next week only brings new ones.
const s = $('Your settings').first().json;
const memory = $getWorkflowStaticData('global');
memory.seen ??= {};
const today = new Date().toISOString().slice(0, 10);
return $input.all().map(({ json: r }) => {
  memory.seen[`${r.kind}|${r.text.toLowerCase()}`] = Date.now();
  return { json: {
    date: today,
    status: 'to review',
    idea: r.title,
    angle: r.angle,
    hook: r.hook,
    format: r.format,
    risingSearch: r.text,
    type: r.kind === 'topic' ? `topic${r.topicType ? ` (${r.topicType})` : ''}` : 'search',
    growth: r.growth,
    seedKeyword: r.keyword,
    googleTrends: `https://trends.google.com/trends/explore?q=${encodeURIComponent(r.text)}&geo=${s.country}&date=${encodeURIComponent(s.timeRange)}`,
  } };
});

// A short message for Slack or Telegram: how many ideas, the top five, and what was filtered out.
const rows = $input.all().map(i => i.json);
const stats = $('Pick the real risers').first().json.stats;
const top = rows.slice(0, 5).map((r, n) => `${n + 1}. ${r.idea} (${r.risingSearch}, ${r.growth})`).join('\n');
const text = `${rows.length} content ideas from rising Google searches in your niche this week.\n\n${top}\n\n`
  + `Found ${stats.risingFound} rising searches, skipped ${stats.noiseRemoved} as off-topic or noise and ${stats.alreadySent} already sent.`;
return [{ json: { text } }];
